      if (k === "prov") return `<p>ה-provenance מחושב בקוד, לא על ידי המודל: מאיזו טבלה, מאיזו מערכת מקור, מתי חולץ, ואילו שורות בדיוק עומדות מאחורי המספר:</p><pre class="l29-code">${esc((d.provenance || []).join("\n"))}</pre>`;
      return "";
